        while scanned < MAX_SCAN and pages < MAX_PAGES:
            batch = (
                items
                if cursor == inicio
                else self._page(inicio=cursor, quantidade=min(MAX_QUANTIDADE, quantidade))
            )
            pages += 1
            if not batch:
                return out
            for it in batch:
